CREATE TYPE "UserRole" AS ENUM ('USER', 'ADMIN');
ALTER TABLE "User" ADD COLUMN "role" "UserRole" NOT NULL DEFAULT 'USER';
ALTER TABLE "User" ADD COLUMN "xp" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "User" ADD COLUMN "streak" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "User" ADD COLUMN "lastActivityDate" TIMESTAMP(3);
CREATE TABLE "VocabularyItem" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "word" TEXT NOT NULL, "definition" TEXT NOT NULL, "example" TEXT, "articleId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "VocabularyItem_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "VocabularyItem_userId_word_key" ON "VocabularyItem"("userId", "word");
CREATE INDEX "VocabularyItem_userId_createdAt_idx" ON "VocabularyItem"("userId", "createdAt");
CREATE TABLE "Achievement" ("id" TEXT NOT NULL, "key" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL, "icon" TEXT NOT NULL, "xpReward" INTEGER NOT NULL, "threshold" INTEGER NOT NULL, "metric" TEXT NOT NULL, CONSTRAINT "Achievement_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Achievement_key_key" ON "Achievement"("key");
CREATE TABLE "UserAchievement" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "achievementId" TEXT NOT NULL, "awardedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "UserAchievement_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "UserAchievement_userId_achievementId_key" ON "UserAchievement"("userId", "achievementId");
CREATE INDEX "UserAchievement_userId_awardedAt_idx" ON "UserAchievement"("userId", "awardedAt");
CREATE TABLE "XpEvent" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "source" TEXT NOT NULL, "amount" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "XpEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "XpEvent_userId_source_key" ON "XpEvent"("userId", "source");
CREATE INDEX "XpEvent_userId_createdAt_idx" ON "XpEvent"("userId", "createdAt");
ALTER TABLE "VocabularyItem" ADD CONSTRAINT "VocabularyItem_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "VocabularyItem" ADD CONSTRAINT "VocabularyItem_articleId_fkey" FOREIGN KEY ("articleId") REFERENCES "Article"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "UserAchievement" ADD CONSTRAINT "UserAchievement_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "UserAchievement" ADD CONSTRAINT "UserAchievement_achievementId_fkey" FOREIGN KEY ("achievementId") REFERENCES "Achievement"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "XpEvent" ADD CONSTRAINT "XpEvent_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "MockTestTemplate" ("id" TEXT NOT NULL, "skill" "MockTestSkill" NOT NULL, "title" TEXT NOT NULL, "sourceSlug" TEXT NOT NULL, "duration" INTEGER NOT NULL DEFAULT 20, "isPublished" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "MockTestTemplate_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "MockTestTemplate_skill_sourceSlug_key" ON "MockTestTemplate"("skill", "sourceSlug");
CREATE INDEX "MockTestTemplate_isPublished_skill_idx" ON "MockTestTemplate"("isPublished", "skill");
